class Book:
    def __init__(self, title, price):
        self.title = title
        self.price = price

class PricingService:
    def discounted_total(self, books, percent):
        total = sum(book.price for book in books)
        return total * (1 - percent / 100)

class Book:
    def __init__(self, title, price):
        self.title = title
        self.price = price

class InventoryService:
    def affordable_titles(self, books, max_price):
        return [book.title for book in books if book.price <= max_price]

class Book:
    def __init__(self, title, price):
        self.title = title
        self.price = price

class SummaryService:
    def build_summary(self, books):
        total = sum(book.price for book in books)
        return f"Books: {len(books)} | Total: ${total}"
